const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

async function loadSecrets() {
  const client = new SecretsManagerClient({ region: 'us-east-1' });
  const response = await client.send(
    new GetSecretValueCommand({ SecretId: 'my-app/production' })
  );
  return JSON.parse(response.SecretString);
}

// Option B: HashiCorp Vault
const vault = require('node-vault')({ endpoint: process.env.VAULT_ADDR });

async function loadSecrets() {
  const result = await vault.read('secret/data/my-app');
  return result.data.data;
}

// Option C: At minimum, validate that required env vars are set at startup
function requireEnv(name) {
  const value = process.env[name];
  if (!value) {
    console.error(`FATAL: Missing required environment variable: ${name}`);
    process.exit(1);
  }
  return value;
}
```

### 3. **Overly broad secrets in a single file**

The file mixes infrastructure credentials (DB, AWS) with third-party API keys (Stripe, Anthropic). These should be scoped and rotated independently.

**Recommendation:** Separate secrets by concern and apply least-privilege:

| Secret | Should Be Accessed By | Rotation Cadence |
|--------|----------------------|------------------|
| `DATABASE_URL` | App server only | 90 days |
| `AWS_ACCESS_KEY_ID` | Specific service roles | Use IAM roles instead |
| `STRIPE_SECRET_KEY` | Payment service only | On compromise |
| `ANTHROPIC_API_KEY` | AI service only | 90 days |

### 4. **No secret rotation or expiration**

Static secrets in `.env` files have no built-in rotation. If compromised, they remain valid indefinitely.

