Instead of `.env` files, load secrets from a dedicated secrets manager:

```js
// Example using AWS Secrets Manager
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

async function loadSecrets() {
  const client = new SecretsManagerClient({ region: 'us-east-1' });
  const command = new GetSecretValueCommand({ SecretId: 'myapp/production' });
  const response = await client.send(command);
  return JSON.parse(response.SecretString);
}

// Or using HashiCorp Vault
const vault = require('node-vault')({ endpoint: process.env.VAULT_ADDR });

async function loadSecrets() {
  const result = await vault.read('secret/data/myapp');
  return result.data.data;
}
```

#### If `dotenv` Must Be Used (dev only)

```js
// Load ONLY in non-production environments
if (process.env.NODE_ENV !== 'production') {
  require('dotenv').config();
}

// Validate required env vars are present at startup
const REQUIRED_ENV = ['DATABASE_URL', 'STRIPE_SECRET_KEY'];
for (const key of REQUIRED_ENV) {
  if (!process.env[key]) {
    console.error(`FATAL: Missing required environment variable: ${key}`);
    process.exit(1);
  }
}
```

